<?php declare(strict_types=1);use FastWebsite\Core\View;?>
<section class="admin-page-heading"><div><p class="eyebrow">Calendar</p><h1>Events</h1><p>Publishing and later edits use the same flexible workflow.</p></div><a class="button button-primary" href="<?=View::escape($baseUrl)?>admin/events/create">Create event</a></section><section class="admin-card"><div class="table-wrap"><table><thead><tr><th>Event</th><th>Starts</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php if($items===[]):?><tr><td colspan="4">No events yet.</td></tr><?php endif;?><?php foreach($items as$i):?><tr><td><strong><?=View::escape($i['title'])?></strong><br><small><?=View::escape($i['category_name'])?></small></td><td><?=View::escape($i['starts_at'])?></td><td><?=View::escape($i['status'])?> · <?=View::escape($i['event_status'])?></td><td><div class="table-actions"><a href="<?=View::escape($baseUrl)?>admin/events/<?=(int)$i['id']?>/edit">Edit</a><?php $action=$i['status']==='published'?'archive':($i['status']==='archived'?'restore':'publish');?><form method="post" action="<?=View::escape($baseUrl)?>admin/events/<?=(int)$i['id']?>/workflow"><input type="hidden" name="_token" value="<?=View::escape($csrfToken)?>"><button class="link-button" name="action" value="<?=$action?>"><?=ucfirst($action)?></button></form></div></td></tr><?php endforeach;?></tbody></table></div></section>
